<template><section class="panel"><div class="panel-title"><h2>{{$t("收费记录与费用查询")}}</h2><el-button size="small" icon="el-icon-refresh" @click="load">{{$t("刷新")}}</el-button></div><div class="toolbar"><el-input v-model.trim="q" clearable :placeholder="$t('患者姓名 / 病历号')" @keyup.enter.native="load"/><el-button @click="load">{{$t("查询")}}</el-button><span class="muted">{{$t("仅未执行项目可以办理退费；已发药品须先退药")}}</span></div><el-table :data="rows" stripe v-loading="loading" show-summary :summary-method="summary"><el-table-column prop="id" :label="$t('费用单号')" min-width="95"/><el-table-column prop="case_number" :label="$t('病历号')" min-width="120"/><el-table-column prop="real_name" :label="$t('患者')" min-width="90"/><el-table-column prop="description" :label="$t('收费项目')" min-width="145"/><el-table-column :label="$t('类别')" width="105"><template slot-scope="s">{{$t(category(s.row.category))}}</template></el-table-column><el-table-column prop="amount" :label="$t('金额（元）')" width="100"/><el-table-column :label="$t('状态')" width="110"><template slot-scope="s"><el-tag size="small" :type="s.row.status==='PAID'?'success':s.row.status==='UNPAID'?'warning':'info'">{{$t(state(s.row.status))}}</el-tag></template></el-table-column><el-table-column v-if="canEdit" :label="$t('操作')" width="140" fixed="right"><template slot-scope="s"><el-button type="text" v-if="s.row.status==='UNPAID'" @click="pay(s.row)">{{$t("收费")}}</el-button><el-button type="text" v-if="s.row.status==='PAID'&&s.row.category!=='REGISTRATION'" @click="refund(s.row)">{{$t("退费")}}</el-button></template></el-table-column></el-table><el-dialog :title="$t('确认收取费用')" :visible.sync="payDialog" append-to-body width="490px" v-if="payRow"><p>{{$t("患者：")}}<strong>{{payRow.real_name}}</strong> · {{$t(payRow.description)}}</p><p>{{$t("应收金额：")}}<strong>¥{{$t(payRow.amount)}}</strong></p><el-form label-position="top"><el-form-item :label="$t('支付方式')"><el-select v-model="payForm.method" class="full"><el-option v-for="x in ['现金','银行卡','微信','支付宝','医保']" :key="x" :value="x" :label="$t(x)"/></el-select></el-form-item><el-form-item :label="$t('实收金额（元）')"><el-input-number v-model="payForm.received" :min="0" :precision="2" :step="1" class="full"/></el-form-item><el-form-item :label="$t('应找零金额')"><strong :class="change<0?'status-red':'status-green'">{{$t(change<0?'实收不足':'¥'+change.toFixed(2))}}</strong></el-form-item></el-form><span slot="footer"><el-button @click="payDialog=false">{{$t("取消")}}</el-button><el-button type="primary" :disabled="change<0" :loading="savingPay" @click="confirmPay">{{$t("确认收费")}}</el-button></span></el-dialog></section></template>
<script>import api from '../api';export default{name:'Billing',props:['user'],data(){return{q:'',rows:[],loading:false,payDialog:false,payRow:null,payForm:{method:'现金',received:0},savingPay:false}},computed:{change(){return this.payRow?Number(this.payForm.received)-Number(this.payRow.amount):0},canEdit(){return['ADMIN','REGISTRAR'].includes(this.user.role)}},created(){this.load()},methods:{state(x){return{UNPAID:'待缴费',PAID:'已缴费',REFUNDED:'已退费',CANCELLED:'已撤销'}[x]||x},category(x){return{REGISTRATION:'挂号费',CHECK:'检查',LAB:'检验',PROCEDURE:'处置',DRUG:'药费'}[x]||x},async load(){this.loading=true;try{this.rows=await api.get('/charges',{params:{q:this.q}})}catch(e){this.$message.error(e.message)}finally{this.loading=false}},summary({columns,data}){let sums=Array(columns.length).fill('');sums[0]='当前页合计';let idx=columns.findIndex(c=>c.property==='amount');if(idx>=0)sums[idx]=`¥${data.reduce((a,r)=>a+Number(r.amount||0),0).toFixed(2)}`;return sums},async chooseMethod(title){try{let r=await this.$confirm(title,'费用操作',{confirmButtonText:'确认',cancelButtonText:'取消',type:'warning',distinguishCancelAndClose:false,showInput:false});return r?true:false}catch{return false}},pay(row){this.payRow=row;this.payForm={method:'现金',received:Number(row.amount)};this.payDialog=true},async confirmPay(){if(this.change<0)return this.$message.error('实收金额不足');if(!await this.chooseMethod(`确认收取 ¥${this.payRow.amount}，找零 ¥${this.change.toFixed(2)}？`))return;this.savingPay=true;try{await api.post(`/charges/${this.payRow.id}/pay`,this.payForm);this.$message.success('收费成功');this.payDialog=false;this.load()}catch(e){this.$message.error(e.message)}finally{this.savingPay=false}},async refund(row){if(!await this.chooseMethod(`确认退回 ¥${row.amount}，项目「${row.description}」？退款前将验证项目状态。`))return;try{await api.post(`/charges/${row.id}/refund`,{method:'现金'});this.$message.success('退费成功');this.load()}catch(e){this.$message.error(e.message)}}}}</script>
